  const add=`<form id="simple-person"><div class="stack">${field('simplePersonName','Nome','text','','required maxlength="80" placeholder="Nome da pessoa"')}<div><label class="simple-label">Faixa etária</label><div class="quick-segments"><label><input type="radio" name="simplePersonType" value="adult" checked><span>Adulto</span></label><label><input type="radio" name="simplePersonType" value="child"><span>Criança</span></label></div></div>${field('simplePersonAge','Idade (opcional)','number','','min="0" max="120" step="1"')}<div><label class="simple-label">Incluir nesta viagem agora?</label><div class="quick-segments"><label><input type="radio" name="simplePersonTrip" value="yes" checked><span>Sim</span></label><label><input type="radio" name="simplePersonTrip" value="no"><span>Não, apenas cadastrar</span></label></div></div><div><label class="simple-label">Participação na caixinha</label><div class="quick-segments"><label><input type="radio" name="simplePersonPays" value="yes" checked><span>Pagante</span></label><label><input type="radio" name="simplePersonPays" value="no"><span>Não pagante</span></label></div><p class="help">Se não entrar agora, esta escolha será usada quando a pessoa for adicionada à viagem.</p></div><button class="button primary">Cadastrar pessoa</button></div></form>`;
